import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.F7eQ-ohH.js";const r="/bzygq/assets/728a20ee86724a839a88b698364e030b.wvU6QGNs.png",n="/bzygq/assets/2200a1ae9dc54afdbb4c36a9bcbbdb29.CYmFlifK.png",s="/bzygq/assets/f0c1e98607124870bd9c4d43a7f49c5f.Cnndrqwm.png",d="/bzygq/assets/fc126c6cc7854a68972a1c80a4472fd5.nG9XSfU0.png",k=JSON.parse('{"title":"05 Redis高可用、哨兵与Cluster","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/Redis/05 Redis高可用、哨兵与Cluster.md","filePath":"Java面试问题汇总/Redis/05 Redis高可用、哨兵与Cluster.md","lastUpdated":1788929995000}'),o={name:"Java面试问题汇总/Redis/05 Redis高可用、哨兵与Cluster.md"};function p(h,e,u,c,S,b){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_05-redis高可用、哨兵与cluster" tabindex="-1">05 Redis高可用、哨兵与Cluster <a class="header-anchor" href="#_05-redis高可用、哨兵与cluster" aria-label="Permalink to &quot;05 Redis高可用、哨兵与Cluster&quot;">​</a></h1><p>Redis 高可用不是一个单独功能，而是一组逐层叠加的架构能力：主从复制提供数据副本和读扩展，Sentinel 在主从复制之上提供自动故障发现和主从切换，Cluster 进一步把数据按槽位分散到多个主节点上，解决单机容量和吞吐瓶颈。三者解决的问题不同，也各自留下了边界：复制不能自动选主，Sentinel 不能分片扩容，Cluster 也不能把所有跨节点一致性问题自动抹平。</p><p>从工程角度看，Redis 高可用回答的是四个问题：数据如何复制出去，主节点故障后谁来切换，数据量超过单机后如何分片，网络分区导致两个主节点时如何降低数据丢失。面试中如果只说“Redis 可以用哨兵或集群保证高可用”，信息量是不够的；更好的表达是沿着复制、自动切换、分片扩展、脑裂治理这条链路讲清楚机制与取舍。</p><h2 id="一、主从复制解决副本与读扩展问题" tabindex="-1">一、主从复制解决副本与读扩展问题 <a class="header-anchor" href="#一、主从复制解决副本与读扩展问题" aria-label="Permalink to &quot;一、主从复制解决副本与读扩展问题&quot;">​</a></h2><p>主从复制（replication）是 Redis 高可用体系的基础能力。它的核心思想是：主节点负责处理写请求，并把写命令传播给一个或多个从节点；从节点保存主节点的数据副本，可以承担读请求，也可以在主节点故障后被提升为新的主节点。</p><p>主从复制主要解决两个问题。第一是数据副本问题，主节点故障后至少还有从节点保存了较新的数据；第二是读扩展问题，读多写少的业务可以把一部分查询流量打到从节点，降低主节点压力。但它本身不解决自动故障转移，因为主节点宕机后，如果没有 Sentinel 或 Cluster 的故障转移机制，从节点不会自动成为业务可写的新主。</p><p><img src="'+r+'" alt="images/redis-14-主从复制链路.png"></p><p>images/redis-14-主从复制链路.png</p><h3 id="_1-全量同步-从节点重新获得完整数据集" tabindex="-1">1. 全量同步：从节点重新获得完整数据集 <a class="header-anchor" href="#_1-全量同步-从节点重新获得完整数据集" aria-label="Permalink to &quot;1\\. 全量同步：从节点重新获得完整数据集&quot;">​</a></h3><p>当从节点第一次连接主节点，或者从节点与主节点之间的复制历史已经对不上时，Redis 会触发全量同步。全量同步的典型过程可以概括为四步：从节点向主节点发起同步请求；主节点生成 RDB 快照；主节点把 RDB 文件发送给从节点；从节点加载 RDB 后，再继续接收主节点在快照生成期间缓冲的写命令。</p><p>全量同步的代价比较高。主节点需要生成快照，占用 CPU、磁盘 I/O 和网络带宽；从节点加载 RDB 时也可能阻塞自身服务。如果从节点频繁断线重连并反复触发全量同步，整个 Redis 实例的稳定性会明显下降。因此生产环境会关注网络质量、实例负载、复制缓冲区大小，以及是否存在从节点频繁重启。</p><p>需要注意的是，全量同步并不意味着复制期间主节点停止写入。主节点在生成和发送 RDB 的同时，还会继续接收客户端写请求，并把这部分新写入保存到复制缓冲中，等从节点加载完 RDB 后再补发过去。也就是说，全量同步是“快照 + 后续命令补齐”的组合，而不是简单地把主节点暂停后复制文件。</p><h3 id="_2-部分重同步-用复制积压缓冲区补齐断线期间的命令" tabindex="-1">2. 部分重同步：用复制积压缓冲区补齐断线期间的命令 <a class="header-anchor" href="#_2-部分重同步-用复制积压缓冲区补齐断线期间的命令" aria-label="Permalink to &quot;2\\. 部分重同步：用复制积压缓冲区补齐断线期间的命令&quot;">​</a></h3><p>Redis 为了避免短暂断线后总是全量同步，引入了部分重同步（partial resynchronization）。从节点会记住自己已经复制到的偏移量，断线重连后把主节点 run id 和复制偏移量带给主节点。如果主节点判断这个从节点仍然属于同一段复制历史，并且从节点缺失的写命令还保存在 replication backlog 中，就可以只补发缺失命令。</p><p>replication backlog 是主节点维护的一段环形复制积压缓冲区，用来保存最近传播过的写命令流。每个写命令都会推进主节点的复制偏移量，从节点收到并执行命令后，也会更新自己的复制偏移量。主从双方通过偏移量判断数据差距：偏移量越接近，说明从节点越接近主节点；差距越大，说明复制延迟越严重。</p><p>部分重同步能否成功，关键取决于断线时间和 backlog 大小。如果从节点断线时间很短，缺失命令仍在 backlog 中，就可以快速补齐；如果断线太久，主节点的 backlog 已经被新的写命令覆盖，从节点只能重新走全量同步。因此，高写入量场景下 backlog 太小会增加全量同步概率，进而放大故障恢复成本。</p><h3 id="_3-复制偏移量与复制延迟怎么观察" tabindex="-1">3. 复制偏移量与复制延迟怎么观察 <a class="header-anchor" href="#_3-复制偏移量与复制延迟怎么观察" aria-label="Permalink to &quot;3\\. 复制偏移量与复制延迟怎么观察&quot;">​</a></h3><p>复制偏移量是理解 Redis 复制状态的关键指标。主节点有自己的 master replication offset，从节点也有自己已经处理到的 replication offset。两者之差可以近似反映从节点落后的字节量。运维或排查时通常会通过 INFO replication 观察主从角色、连接状态、偏移量、backlog 状态和从节点延迟。</p><p>复制延迟的来源不只是一条网络链路。主节点写入压力过高、从节点机器性能较弱、网络抖动、从节点正在加载大 RDB、慢命令阻塞事件循环，都可能让从节点落后。Redis 的复制是异步复制，主节点通常不会等待从节点确认后才返回写成功，所以“写成功”只代表主节点已经处理成功，不代表所有从节点都立刻拥有这条数据。</p><p>这也是读写分离最容易被忽略的风险。如果业务刚写入一条订单状态，马上从从节点读取，可能读到旧值。对一致性要求高的读，可以选择读主节点；对允许短暂延迟的读，例如商品详情、排行榜、推荐缓存，可以读从节点。更稳妥的设计是按业务语义区分读路径，而不是机械地把所有读都打到从库。</p><h3 id="_4-主从复制解决什么-不解决什么" tabindex="-1">4. 主从复制解决什么，不解决什么 <a class="header-anchor" href="#_4-主从复制解决什么-不解决什么" aria-label="Permalink to &quot;4\\. 主从复制解决什么，不解决什么&quot;">​</a></h3><p>主从复制解决的是“数据副本”和“读扩展”，不解决“自动选主”和“强一致提交”。它可以让系统具备恢复基础，但并不等于完整高可用。主节点宕机时，单纯复制架构仍然需要人工提升从节点、修改其他从节点复制关系、更新客户端连接地址，这个过程存在明显恢复窗口。</p><p>在面试里回答主从复制，可以按下面的逻辑组织：Redis 主从复制通过全量同步建立初始副本，通过命令传播维持增量同步，通过复制偏移量和 replication backlog 支持短暂断线后的部分重同步。它能提升读能力和容灾能力，但因为复制默认是异步的，所以会带来复制延迟和读到旧数据的问题；如果要自动故障转移，需要继续引入 Sentinel 或 Cluster。</p><h2 id="二、sentinel-解决主从架构下的自动切换问题" tabindex="-1">二、Sentinel 解决主从架构下的自动切换问题 <a class="header-anchor" href="#二、sentinel-解决主从架构下的自动切换问题" aria-label="Permalink to &quot;二、Sentinel 解决主从架构下的自动切换问题&quot;">​</a></h2><p>Sentinel（哨兵）是运行在特殊模式下的 Redis 进程。它不负责存储业务数据，而是负责监控 Redis 主从节点、判断主节点是否不可用、在必要时选出新的主节点，并向客户端发布新的主节点地址。Sentinel 解决的是“主从复制已经存在，但主节点故障后如何自动完成切换”的问题。</p><p>Sentinel 通常以多个节点部署，避免单个 Sentinel 自己故障或误判。每个 Sentinel 会周期性地向 Redis 主从节点发送探测请求，也会与其他 Sentinel 交换状态信息。只有当多个 Sentinel 对主节点故障形成足够一致的判断后，才会进入故障转移流程。</p><p><img src="'+n+'" alt="images/redis-15-Sentinel故障转移.png"></p><p>images/redis-15-Sentinel故障转移.png</p><h3 id="_1-主观下线与客观下线的区别" tabindex="-1">1. 主观下线与客观下线的区别 <a class="header-anchor" href="#_1-主观下线与客观下线的区别" aria-label="Permalink to &quot;1\\. 主观下线与客观下线的区别&quot;">​</a></h3><p>Sentinel 的故障判断分为主观下线（subjectively down）和客观下线（objectively down）。主观下线是单个 Sentinel 的本地判断：如果它在 down-after-milliseconds 指定时间内没有收到主节点的有效响应，就会认为主节点不可达。这个判断可能是主节点真的故障，也可能只是这个 Sentinel 到主节点之间的网络异常。</p><p>客观下线需要多个 Sentinel 共同确认。当一个 Sentinel 认为主节点主观下线后，会询问其他 Sentinel 是否也认为该主节点下线。如果达到配置中的 quorum 数量，主节点才会被判定为客观下线。quorum 的作用不是选举新主，而是决定“故障判断是否成立”；它越小，切换更敏感但误判风险更高；它越大，误判更少但故障确认可能更慢。</p><p>实际部署中，Sentinel 节点数通常设置为奇数，例如 3 个或 5 个。这样在网络分区或部分节点宕机时，更容易形成多数派判断。需要强调的是，quorum 不等同于 Sentinel 总数的一半加一；quorum 是配置的客观下线确认阈值，而 Sentinel leader 选举还需要满足多数派投票约束。</p><h3 id="_2-leader-sentinel-负责执行故障转移" tabindex="-1">2. leader Sentinel 负责执行故障转移 <a class="header-anchor" href="#_2-leader-sentinel-负责执行故障转移" aria-label="Permalink to &quot;2\\. leader Sentinel 负责执行故障转移&quot;">​</a></h3><p>当主节点被判定为客观下线后，并不是所有 Sentinel 同时执行切换。Sentinel 之间会先选举一个 leader Sentinel，由它负责本轮故障转移。这样可以避免多个 Sentinel 同时提升不同从节点，造成切换混乱。</p><p>leader Sentinel 选出后，会在从节点中挑选一个最适合提升为主节点的候选者。选择时会排除状态异常、断线时间过长、配置为不适合提升的从节点；在可用候选者中，会综合考虑从节点优先级、复制偏移量和运行标识等因素。复制偏移量更靠前的从节点通常拥有更完整的数据，因此更适合作为新主。</p><p>这个过程体现了 Sentinel 的一个重要边界：它尽量选择数据最新的从节点，但不能保证零丢失。因为 Redis 复制本身是异步的，如果旧主在宕机前已经向客户端返回写成功，但这条写命令还没复制到任何从节点，那么故障转移后这部分数据仍然可能丢失。</p><h3 id="_3-故障转移流程如何展开" tabindex="-1">3. 故障转移流程如何展开 <a class="header-anchor" href="#_3-故障转移流程如何展开" aria-label="Permalink to &quot;3\\. 故障转移流程如何展开&quot;">​</a></h3><p>Sentinel 故障转移可以拆成五个阶段。第一，监控阶段，Sentinel 持续探测主从节点和其他 Sentinel。第二，判定阶段，从主观下线升级到客观下线。第三，选举阶段，多个 Sentinel 选出 leader Sentinel。第四，切换阶段，leader Sentinel 向被选中的从节点发送命令，使其提升为新主，并让其他从节点改为复制新主。第五，通知阶段，Sentinel 更新主节点信息，并通过发布订阅、客户端查询等方式让客户端发现新主。</p><p>客户端发现是 Sentinel 架构能否真正落地的关键。支持 Sentinel 的客户端一般不会把主节点地址写死，而是配置一组 Sentinel 地址和 master name。客户端启动或重连时先询问 Sentinel 当前主节点是谁，再连接到实际主节点。故障转移完成后，客户端需要感知连接失败、重新向 Sentinel 查询新主地址，并重建连接池。</p><p>如果客户端没有正确接入 Sentinel，而是仍然写死旧主地址，那么 Sentinel 即使完成故障转移，业务也可能继续连接失败。因此，Sentinel 不是只改 Redis 服务端配置，还需要客户端、连接池、超时重试和服务发现方式一起配合。</p><h3 id="_4-sentinel-解决什么-不解决什么" tabindex="-1">4. Sentinel 解决什么，不解决什么 <a class="header-anchor" href="#_4-sentinel-解决什么-不解决什么" aria-label="Permalink to &quot;4\\. Sentinel 解决什么，不解决什么&quot;">​</a></h3><p>Sentinel 解决的是主从架构中的自动故障转移。它让 Redis 在主节点故障后能够自动选出新主，减少人工介入和恢复时间。它不解决单机容量瓶颈，因为所有数据仍然属于同一份主从数据集；它也不解决跨机房强一致，故障转移期间仍然可能存在短暂不可写、客户端重连和少量数据丢失风险。</p><p>面试中可以这样表达 Sentinel：Sentinel 是 Redis 主从架构的高可用组件，它通过多哨兵监控主节点状态，先由单个哨兵形成主观下线，再通过 quorum 达成客观下线，随后选举 leader Sentinel 执行故障转移。leader 会选择复制状态较好的从节点提升为新主，让其他从节点复制新主，并通知客户端刷新主节点地址。</p><h2 id="三、cluster-解决分片扩展与节点级高可用问题" tabindex="-1">三、Cluster 解决分片扩展与节点级高可用问题 <a class="header-anchor" href="#三、cluster-解决分片扩展与节点级高可用问题" aria-label="Permalink to &quot;三、Cluster 解决分片扩展与节点级高可用问题&quot;">​</a></h2><p>Redis Cluster 是 Redis 的分布式集群方案。它的核心不是简单部署多台 Redis，而是把整个 key 空间划分为 16384 个 hash slot，每个主节点负责其中一部分槽位。客户端访问某个 key 时，先根据 key 计算槽位，再访问负责该槽位的主节点。</p><p>Cluster 主要解决两个问题。第一是容量扩展，数据可以分散到多个主节点，突破单机内存限制。第二是吞吐扩展，不同槽位的请求可以分散到不同主节点处理。与此同时，Cluster 也内置主从故障转移能力，每个主节点通常配置一个或多个从节点，主节点故障后由对应从节点接替它负责的槽位。</p><p><img src="'+s+'" alt="images/redis-17-Cluster槽位分片.png"></p><p>images/redis-17-Cluster槽位分片.png</p><h3 id="_1-16384-个-slot-与-crc16-计算" tabindex="-1">1. 16384 个 slot 与 CRC16 计算 <a class="header-anchor" href="#_1-16384-个-slot-与-crc16-计算" aria-label="Permalink to &quot;1\\. 16384 个 slot 与 CRC16 计算&quot;">​</a></h3><p>Cluster 使用槽位作为数据分片单位，而不是直接把每个 key 映射到具体机器。普通 key 的槽位计算方式是：先对 key 做 CRC16，再对 16384 取模，得到 0 到 16383 之间的槽位编号。每个主节点负责一段或多段槽位，集群通过维护“槽位 -&gt; 节点”的映射关系来路由请求。</p><p>引入槽位的好处是迁移和扩容更容易控制。如果直接按节点数对 key 取模，节点数量变化时大量 key 都需要重新映射；而 Cluster 以 slot 为中间层，扩容时只需要把一部分槽位迁移到新节点，缩容时把待下线节点的槽位迁移到其他节点。槽位是稳定的逻辑分片单位，节点只是槽位的承载者。</p><p>Cluster 选择 16384 个槽位，是在路由表大小、迁移粒度和集群通信成本之间做的折中。槽位数量足够多，可以较细粒度地分配到多个主节点；同时又不会让每个节点维护过大的槽位位图和集群元数据。</p><h3 id="_2-hash-tag-让相关-key-落到同一槽位" tabindex="-1">2. hash tag 让相关 key 落到同一槽位 <a class="header-anchor" href="#_2-hash-tag-让相关-key-落到同一槽位" aria-label="Permalink to &quot;2\\. hash tag 让相关 key 落到同一槽位&quot;">​</a></h3><p>Cluster 对多 key 操作有天然限制，因为多个 key 可能分布在不同槽位、不同主节点上。为了让相关 key 落到同一个槽位，Redis 提供 hash tag 机制：如果 key 中包含 {}，Cluster 会优先使用花括号内的内容计算槽位。例如 order:{1001}:detail 和 order:{1001}:items 会使用 1001 计算槽位，因此落到同一个 slot。</p><p>hash tag 常用于需要原子处理的一组相关 key，例如同一用户的购物车、订单明细、库存预扣记录等。它不是为了让所有 key 都集中到一个槽位，而是为了把确实需要一起操作的少量 key 放在一起。如果滥用 hash tag，把大量热点 key 固定到同一槽位，反而会造成单槽位热点，削弱 Cluster 的分片效果。</p><p>因此，Cluster 下设计 key 时要同时考虑两个目标：一方面让大多数 key 均匀分布，充分利用多个主节点；另一方面把确实需要多 key 原子操作或事务处理的相关 key 放在同一槽位。这个平衡是 Cluster 架构设计中很常见的追问点。</p><h3 id="_3-moved-与-ask-重定向" tabindex="-1">3. MOVED 与 ASK 重定向 <a class="header-anchor" href="#_3-moved-与-ask-重定向" aria-label="Permalink to &quot;3\\. MOVED 与 ASK 重定向&quot;">​</a></h3><p>客户端请求可能会打到错误节点。比如客户端缓存的槽位映射过期，或者集群正在迁移槽位。这时 Redis 节点会返回重定向响应，让客户端去正确节点执行命令。</p><p>MOVED 表示槽位已经稳定归属于另一个节点，客户端应该更新本地槽位映射表，后续同一槽位请求都发往新节点。ASK 表示槽位正在迁移过程中，当前请求需要临时访问迁移目标节点，但不代表槽位归属已经最终变更。客户端收到 ASK 后，一般需要先向目标节点发送 ASKING，再执行实际命令。</p><p>两者的区别可以简单记为：MOVED 是永久重定向，ASK 是迁移过程中的临时重定向。面试中如果能讲清这个区别，说明不是只背了“Cluster 会重定向”，而是理解了槽位迁移期间的请求路由。</p><h3 id="_4-扩容、缩容与槽位迁移" tabindex="-1">4. 扩容、缩容与槽位迁移 <a class="header-anchor" href="#_4-扩容、缩容与槽位迁移" aria-label="Permalink to &quot;4\\. 扩容、缩容与槽位迁移&quot;">​</a></h3><p>Cluster 扩容的本质是新增节点并迁移一部分槽位。新增 Redis 节点加入集群后，起初不负责任何槽位；随后运维工具或管理程序会从原有主节点迁移一部分槽位到新节点。迁移过程中，源节点和目标节点会配合移动 key，并通过 ASK 重定向处理正在迁移槽位上的请求。</p><p>缩容则相反。要下线某个主节点，必须先把它负责的槽位迁移到其他主节点，等该节点不再负责任何槽位后，才能安全从集群中移除。如果直接下线仍然持有槽位的主节点，集群会出现槽位不可用，相关 key 无法正常访问。</p><p>槽位迁移会带来额外网络和 CPU 开销，迁移期间还可能增加请求延迟。因此生产环境扩缩容通常会选择低峰期，控制每批迁移槽位数量，并持续观察延迟、失败请求和集群状态。Cluster 能扩展容量，但扩展不是零成本动作。</p><h3 id="_5-cluster-主从故障转移" tabindex="-1">5. Cluster 主从故障转移 <a class="header-anchor" href="#_5-cluster-主从故障转移" aria-label="Permalink to &quot;5\\. Cluster 主从故障转移&quot;">​</a></h3><p>Cluster 中每个主节点可以配置一个或多个从节点。从节点复制对应主节点的数据，并在主节点故障时参与故障转移。与 Sentinel 类似，Cluster 也需要判断主节点是否下线，并由其他节点投票确认；当主节点被认定故障后，它的从节点会竞争提升为新的主节点，接管原主节点负责的槽位。</p><p>Cluster 的故障转移是按分片进行的。某个主节点故障时，只影响它负责的槽位；其他主节点负责的槽位仍然可以服务。这是 Cluster 相比单主多从架构的重要优势。但如果一个主节点及其所有从节点都不可用，那么该主节点负责的槽位就会不可用，集群能否继续对外提供服务还取决于配置和业务容忍度。</p><p>需要注意的是，Cluster 的高可用仍然建立在异步复制基础上。主节点故障前尚未复制到从节点的写入，故障转移后也可能丢失。因此 Cluster 提供的是分片级可用性和自动切换能力，不是强一致分布式事务。</p><h3 id="_6-跨槽限制与业务设计边界" tabindex="-1">6. 跨槽限制与业务设计边界 <a class="header-anchor" href="#_6-跨槽限制与业务设计边界" aria-label="Permalink to &quot;6\\. 跨槽限制与业务设计边界&quot;">​</a></h3><p>Cluster 对跨槽操作有明确限制。多 key 命令、事务和 Lua 脚本如果涉及多个槽位，通常无法直接执行，因为 Redis 无法在多个主节点之间提供单机式原子性。常见报错是 CROSSSLOT Keys in request don&#39;t hash to the same slot。</p><p>工程上有三类处理方式。第一，把确实需要原子处理的 key 通过 hash tag 放到同一槽位。第二，把跨 key 操作上移到业务层，通过状态机、幂等、补偿任务等方式保证最终一致。第三，重新评估是否应该使用 Redis Cluster 承载这类强一致多 key 场景，有时关系数据库、消息队列或专门的分布式事务设计更合适。</p><p>所以 Cluster 解决的是容量扩展和分片高可用，不适合被表达成“Redis 版分布式数据库”。它保留了 Redis 高性能 key-value 的定位，只是在路由、分片和节点故障转移上做了集群化。</p><h2 id="四、脑裂治理解决网络分区下的数据丢失风险" tabindex="-1">四、脑裂治理解决网络分区下的数据丢失风险 <a class="header-anchor" href="#四、脑裂治理解决网络分区下的数据丢失风险" aria-label="Permalink to &quot;四、脑裂治理解决网络分区下的数据丢失风险&quot;">​</a></h2><p>脑裂通常发生在网络分区场景。旧主节点与 Sentinel、Cluster 多数节点或部分从节点失联，但仍然能被一部分客户端访问并继续接收写入；另一侧多数派认为旧主已经故障，于是完成故障转移并产生新主。网络恢复后，旧主会被降级为从节点，并重新同步新主数据，它在分区期间接收但没有复制到新主的写入就可能丢失。</p><p><img src="'+d+'" alt="images/redis-16-脑裂与写保护.png"></p><p>images/redis-16-脑裂与写保护.png</p><h3 id="_1-脑裂为什么会发生" tabindex="-1">1. 脑裂为什么会发生 <a class="header-anchor" href="#_1-脑裂为什么会发生" aria-label="Permalink to &quot;1\\. 脑裂为什么会发生&quot;">​</a></h3><p>脑裂不是 Redis 独有问题，而是分布式系统在网络分区下的典型风险。Redis 复制默认异步，旧主是否还能接收客户端写入，取决于客户端能否连上它；而 Sentinel 或 Cluster 的多数派判断则取决于监控节点之间的网络可达性。当客户端所在网络与旧主仍然连通，但旧主与多数派监控节点断开时，就可能出现“业务还在写旧主，集群已经选出新主”的局面。</p><p>这种风险在跨机房、网络抖动、客户端连接地址配置不规范、故障判定时间过短时更容易暴露。尤其是客户端没有正确接入 Sentinel 或 Cluster 路由，而是长期持有旧主连接时，即使服务端已经完成切换，仍可能继续把请求打到错误节点。</p><p>脑裂真正危险的地方不只是出现两个主节点，而是恢复后的数据取舍。Redis 会让旧主重新成为从节点并同步新主数据，这意味着旧主分区期间独自接收的写入会被覆盖。从业务视角看，这就是“客户端收到写成功，但故障恢复后数据不见了”。</p><h3 id="_2-用-min-replicas-to-write-限制孤立主继续写" tabindex="-1">2. 用 min-replicas-to-write 限制孤立主继续写 <a class="header-anchor" href="#_2-用-min-replicas-to-write-限制孤立主继续写" aria-label="Permalink to &quot;2\\. 用 min-replicas-to-write 限制孤立主继续写&quot;">​</a></h3><p>Redis 提供了 min-replicas-to-write 和 min-replicas-max-lag 两个参数，用来降低孤立主继续写入的风险。min-replicas-to-write 表示主节点至少需要拥有多少个延迟可接受的从节点，才允许继续处理写命令；min-replicas-max-lag 表示从节点延迟超过多少秒后，就不再被认为是合格从节点。</p><p>例如，配置 min-replicas-to-write 1 和 min-replicas-max-lag 10，表示主节点至少要有 1 个最近 10 秒内仍然跟得上的从节点，才继续接受写入。如果旧主因为网络分区失去了从节点确认，它就会拒绝写请求，从而减少脑裂期间产生的孤立写入。</p><p>这两个参数不能把 Redis 变成强一致系统，但能把风险从“旧主无限制接收写入”降低为“旧主在缺少健康从节点时主动拒绝写入”。它牺牲的是分区时的部分可写性，换来的是更低的数据丢失概率。对金融状态、库存扣减、订单流转这类敏感业务，通常应该认真评估这类写保护策略。</p><h3 id="_3-合理设置超时、监控和客户端行为" tabindex="-1">3. 合理设置超时、监控和客户端行为 <a class="header-anchor" href="#_3-合理设置超时、监控和客户端行为" aria-label="Permalink to &quot;3\\. 合理设置超时、监控和客户端行为&quot;">​</a></h3><p>脑裂治理不能只靠一个参数。Sentinel 的 down-after-milliseconds、故障转移超时、客户端连接超时、重试策略都需要配合。如果故障判断过于激进，短暂网络抖动就可能触发切主；如果判断过于保守，主节点真实故障后恢复时间又会变长。</p><p>监控上至少要关注复制延迟、主从偏移量差距、从节点断连次数、故障转移次数、拒绝写入次数、网络丢包和慢命令。很多 Redis 高可用事故并不是机制完全失效，而是复制延迟已经持续升高、从节点频繁断开、backlog 不够用，却没有在切换前被发现。</p><p>客户端侧也要避免长期写死单个节点地址。Sentinel 架构下，客户端应该通过 Sentinel 查询当前主节点；Cluster 架构下，客户端应该支持槽位缓存和 MOVED/ASK 重定向。否则服务端拓扑已经变化，客户端仍然可能把请求送到旧地址，放大脑裂和写入失败风险。</p><h2 id="五、sentinel-与-cluster-的架构选型" tabindex="-1">五、Sentinel 与 Cluster 的架构选型 <a class="header-anchor" href="#五、sentinel-与-cluster-的架构选型" aria-label="Permalink to &quot;五、Sentinel 与 Cluster 的架构选型&quot;">​</a></h2><p>Sentinel 和 Cluster 都能提高可用性，但它们不是同一层方案。Sentinel 适合单份数据集仍然能放进单机内存、主要诉求是主节点故障自动切换的场景；Cluster 适合数据规模或吞吐超过单机，需要把 key 分散到多个主节点的场景。</p><table tabindex="0"><thead><tr><th>对比维度</th><th>Sentinel 主从高可用</th><th>Redis Cluster</th></tr></thead><tbody><tr><td>主要目标</td><td>单主数据集的自动故障转移</td><td>分片扩容 + 分片级故障转移</td></tr><tr><td>数据分布</td><td>所有节点保存同一份数据的副本</td><td>key 按 16384 个 slot 分布到多个主节点</td></tr><tr><td>扩容方式</td><td>通常只能提升单机规格或增加读从库</td><td>新增节点并迁移槽位</td></tr><tr><td>客户端要求</td><td>支持通过 Sentinel 发现当前主节点</td><td>支持槽位路由、MOVED/ASK 重定向</td></tr><tr><td>多 key 操作</td><td>单主上限制较少</td><td>要求相关 key 尽量落在同一槽位</td></tr><tr><td>典型风险</td><td>复制延迟、切换窗口、脑裂</td><td>跨槽限制、槽位迁移成本、分片热点</td></tr></tbody></table><p>选型时可以先问三个问题。第一，数据量和写入吞吐是否已经超过单机可承载范围；如果没有，Sentinel 架构更简单。第二，业务是否大量依赖多 key 原子操作；如果依赖很重，Cluster 的跨槽限制会增加改造成本。第三，团队是否具备集群运维能力；Cluster 扩缩容、槽位迁移、客户端兼容性都需要更成熟的治理。</p><p>面试中如果被问“哨兵和集群有什么区别”，不要只答“哨兵高可用，集群分布式”。更完整的说法是：哨兵是在一主多从架构上做监控、选主和客户端通知，数据仍然是一份完整副本；Cluster 是把 key 空间切成 16384 个槽位，分散到多个主节点上，同时为每个分片提供主从复制和故障转移。前者解决自动切主，后者解决容量和吞吐扩展，但也引入跨槽限制和槽位迁移复杂度。</p><h2 id="六、常见面试追问" tabindex="-1">六、常见面试追问 <a class="header-anchor" href="#六、常见面试追问" aria-label="Permalink to &quot;六、常见面试追问&quot;">​</a></h2><h3 id="_1-redis-主从复制为什么会丢数据" tabindex="-1">1. Redis 主从复制为什么会丢数据 <a class="header-anchor" href="#_1-redis-主从复制为什么会丢数据" aria-label="Permalink to &quot;1\\. Redis 主从复制为什么会丢数据&quot;">​</a></h3><p>因为 Redis 复制默认是异步的。主节点执行写命令并返回成功后，该命令可能还没有传播到从节点。如果主节点此时宕机，Sentinel 或 Cluster 只能从已有从节点中选出新主，未复制出去的写入就会丢失。可以通过 WAIT 命令、写保护参数、减少复制延迟等方式降低风险，但 Redis 主从复制本身不是强一致提交协议。</p><h3 id="_2-全量同步和部分重同步怎么区分" tabindex="-1">2. 全量同步和部分重同步怎么区分 <a class="header-anchor" href="#_2-全量同步和部分重同步怎么区分" aria-label="Permalink to &quot;2\\. 全量同步和部分重同步怎么区分&quot;">​</a></h3><p>全量同步用于从节点没有可用复制历史，或者缺失数据已经无法从主节点 backlog 中补齐的情况，需要传输 RDB 快照并补发期间写命令。部分重同步用于短暂断线后，从节点携带旧的 run id 和复制偏移量重连，主节点发现缺失命令仍在 replication backlog 中，于是只补发差量命令。前者成本高，后者恢复快。</p><h3 id="_3-sentinel-的-quorum-是不是越大越好" tabindex="-1">3. Sentinel 的 quorum 是不是越大越好 <a class="header-anchor" href="#_3-sentinel-的-quorum-是不是越大越好" aria-label="Permalink to &quot;3\\. Sentinel 的 quorum 是不是越大越好&quot;">​</a></h3><p>不是。quorum 太小，少数 Sentinel 误判就可能触发客观下线；quorum 太大，真实故障时又可能因为无法达到确认阈值而迟迟不切换。它需要结合 Sentinel 总数、网络拓扑和故障容忍目标设置。常见做法是部署 3 个或 5 个 Sentinel，并让配置能够在少数节点异常时仍然形成有效判断。</p><h3 id="_4-sentinel-为什么还需要-leader" tabindex="-1">4. Sentinel 为什么还需要 leader <a class="header-anchor" href="#_4-sentinel-为什么还需要-leader" aria-label="Permalink to &quot;4\\. Sentinel 为什么还需要 leader&quot;">​</a></h3><p>客观下线只说明“大家认为主节点故障了”，但真正执行故障转移需要一个协调者。leader Sentinel 负责选择新主、发送提升命令、重配其他从节点、发布切换结果。如果没有 leader，多个 Sentinel 可能同时执行不同切换决策，导致拓扑不一致。</p><h3 id="_5-cluster-为什么是-16384-个槽" tabindex="-1">5. Cluster 为什么是 16384 个槽 <a class="header-anchor" href="#_5-cluster-为什么是-16384-个槽" aria-label="Permalink to &quot;5\\. Cluster 为什么是 16384 个槽&quot;">​</a></h3><p>Cluster 通过固定数量的槽位作为 key 与节点之间的中间层。16384 个槽位提供了足够细的分配粒度，又不会让每个节点维护过大的槽位元数据。扩容缩容时迁移的是槽位，不是重新计算全部 key 到节点的映射。</p><h3 id="_6-moved-和-ask-有什么区别" tabindex="-1">6. MOVED 和 ASK 有什么区别 <a class="header-anchor" href="#_6-moved-和-ask-有什么区别" aria-label="Permalink to &quot;6\\. MOVED 和 ASK 有什么区别&quot;">​</a></h3><p>MOVED 表示槽位已经归属于另一个节点，客户端应该更新本地槽位映射；ASK 表示槽位正在迁移，本次请求临时去目标节点执行，客户端不应把槽位归属永久改掉。MOVED 面向稳定拓扑变更，ASK 面向迁移过程中的临时路由。</p><h3 id="_7-cluster-里多-key-命令为什么容易报错" tabindex="-1">7. Cluster 里多 key 命令为什么容易报错 <a class="header-anchor" href="#_7-cluster-里多-key-命令为什么容易报错" aria-label="Permalink to &quot;7\\. Cluster 里多 key 命令为什么容易报错&quot;">​</a></h3><p>因为多个 key 可能位于不同槽位，而不同槽位可能由不同主节点负责。Redis 无法跨多个主节点提供单机式原子执行，所以会报 CROSSSLOT。解决方式是用 hash tag 让相关 key 落到同一槽位，或者把跨 key 一致性逻辑放到业务层处理。</p><h3 id="_8-如何描述-redis-脑裂治理" tabindex="-1">8. 如何描述 Redis 脑裂治理 <a class="header-anchor" href="#_8-如何描述-redis-脑裂治理" aria-label="Permalink to &quot;8\\. 如何描述 Redis 脑裂治理&quot;">​</a></h3><p>可以从三个层面回答：服务端通过多数派判断减少误切，通过 min-replicas-to-write 和 min-replicas-max-lag 限制孤立主继续写入；客户端通过 Sentinel 或 Cluster 正确发现新主或新槽位，避免继续写旧节点；监控上关注复制延迟、主从偏移量、网络抖动和故障转移次数。治理目标不是绝对消除分布式风险，而是降低误切和数据丢失概率。</p><h2 id="七、本章掌握标准" tabindex="-1">七、本章掌握标准 <a class="header-anchor" href="#七、本章掌握标准" aria-label="Permalink to &quot;七、本章掌握标准&quot;">​</a></h2><p>这一章准备到位的标准不是背出“主从、哨兵、集群”三个名词，而是能按问题链路解释清楚：主从复制如何通过全量同步、部分重同步、replication backlog 和复制偏移量维持副本；Sentinel 如何从主观下线、客观下线走到 leader 故障转移和客户端发现；Cluster 如何用 16384 个 slot、CRC16、hash tag、MOVED/ASK 和槽位迁移完成分片扩展；脑裂为什么会发生，以及如何用写保护、超时配置、客户端发现和监控来降低风险。</p>',112)])])}const _=a(o,[["render",p]]);export{k as __pageData,_ as default};
